/** An inline 16px Octicon as an SVG string. */
export const icon = (name, { size = 16, cls = '' } = {}) =>
  `<svg class="octicon ${cls}" viewBox="0 0 16 16" width="${size}" height="${size}" fill="currentColor" aria-hidden="true">${PATHS[name] || ''}</svg>`;
